//! Each consumer's `deny.toml`, so the consumer can check its copy against the core it pins —
//! task `32d7c04d`.
//!
//! The configs are generated by `cargo xtask gen-deny` from this repository's own `deny.toml` and
//! committed under `supply-chain/`. This module is the half that lets a CONSUMER verify its copy:
//! a repository that takes this core cannot read our repository files, but it already compiles
//! this crate, so the bytes travel with the pin.
//!
//! That makes the check mean something exact. A consumer's test does not ask "does this match
//! astrid-core's `main`" — it asks "does this match the astrid-core revision I pin", which is the
//! only question it can act on, and the answer changes when the pin is bumped. Nothing crosses
//! between the repositories implicitly, which was the objection every one of these files' headers
//! raised against a shared config in the first place.
//!
//! ```
//! # let committed = astrid_core::supply_chain::ASTRID_WINDOWS;
//! assert!(astrid_core::supply_chain::matches("astrid-windows", committed));
//! ```

/// This repository's own config — the SOURCE every copy below is rendered from.
///
/// Exposed for completeness and for anyone auditing the chain; a consumer should compare against
/// its own entry, not this one, because this one still carries the empty `allow-git` that would
/// deny the git dependency on this core.
pub const SOURCE: &str = include_str!("../../../deny.toml");

/// astrid-windows' copy, checked by `crates/astrid-ffi/tests/supply_chain_contract.rs`.
pub const ASTRID_WINDOWS: &str = include_str!("../../../supply-chain/deny.astrid-windows.toml");

/// astrid-ios' copy, for `core/deny.toml` in that repository.
pub const ASTRID_IOS: &str = include_str!("../../../supply-chain/deny.astrid-ios.toml");

/// astrid-android's copy, for `core/deny.toml` in that repository.
pub const ASTRID_ANDROID: &str = include_str!("../../../supply-chain/deny.astrid-android.toml");

/// Every generated copy, by the repository it belongs to.
pub const CONSUMERS: &[(&str, &str)] = &[
    ("astrid-windows", ASTRID_WINDOWS),
    ("astrid-ios", ASTRID_IOS),
    ("astrid-android", ASTRID_ANDROID),
];

/// The config a named repository should be carrying, or `None` if it takes none.
///
/// `None` rather than a panic, but a consumer's own test should treat it as a failure: a name that
/// answers nothing means the repository was renamed or was never added to the generator, and
/// comparing against nothing would pass forever.
pub fn deny_toml(repo: &str) -> Option<&'static str> {
    CONSUMERS
        .iter()
        .find(|(name, _)| *name == repo)
        .map(|(_, config)| *config)
}

/// Whether `actual` is the config this core generated for `repo`, ignoring line endings.
///
/// **Not a byte comparison, deliberately.** `core.autocrlf=true` in one checkout and not the other
/// is the ordinary state of a Windows machine, and it makes every committed file differ in the
/// working tree while the committed bytes are identical. Task `f1c7b53f` learned that the
/// expensive way: `check-contracts` reported all thirteen fixtures as drift and told the developer
/// to regenerate files that were already correct. A consumer whose gate said "your deny.toml is
/// not the core's" for that reason would be worse than no gate.
///
/// A repository with no generated copy is `false`, never a vacuous pass.
pub fn matches(repo: &str, actual: &str) -> bool {
    deny_toml(repo).is_some_and(|expected| lf_endings(actual) == lf_endings(expected))
}

fn lf_endings(text: &str) -> String {
    text.replace("\r\n", "\n")
}

#[cfg(test)]
mod tests {
    use super::{deny_toml, matches, ASTRID_WINDOWS, CONSUMERS, SOURCE};

    /// Each copy is a config, carries its generated header, and allows this core by git. A path
    /// typo in an `include_str!` is a compile error; a copy pointing at the WRONG file is not, and
    /// this is what would catch it.
    #[test]
    fn every_copy_is_its_own_repos_config_32d7c04d() {
        for (repo, config) in CONSUMERS {
            assert!(
                config.starts_with(&format!("# GENERATED for {repo} by")),
                "{repo}'s copy should be headed for {repo}, starts: {:?}",
                &config[..config.len().min(80)]
            );
            assert!(config.contains("[licenses]"), "{repo} has no licence table");
            assert!(
                config.contains(
                    "allow-git = [\"https://github.com/Graceful-Tools/astrid-core.git\"]"
                ),
                "{repo} should allow this core by git"
            );
        }
        assert_eq!(CONSUMERS.len(), 3);
    }

    /// The source is NOT a consumer's copy: it carries the empty `allow-git` that would deny the
    /// dependency on this very core. Handing it to a consumer would be a gate that fails on the
    /// core itself, pointing at everything except the cause.
    #[test]
    fn the_source_is_not_a_consumers_copy_32d7c04d() {
        assert!(SOURCE.contains("allow-git = []"));
        assert!(!matches("astrid-windows", SOURCE));
    }

    /// A checkout's line endings are not drift — task `f1c7b53f`.
    #[test]
    fn line_endings_are_not_drift_32d7c04d() {
        assert!(matches("astrid-windows", ASTRID_WINDOWS));
        assert!(matches(
            "astrid-windows",
            &ASTRID_WINDOWS.replace('\n', "\r\n")
        ));
    }

    /// A repository nobody generates for answers nothing, and compares as `false`. A vacuous pass
    /// here would be a consumer believing it was checked for as long as the name stayed wrong.
    #[test]
    fn an_unknown_repo_is_never_a_vacuous_pass_32d7c04d() {
        assert_eq!(deny_toml("astrid-web"), None);
        assert!(!matches("astrid-web", ""));
        assert!(!matches("astrid-windows", "[licenses]\n"));
    }
}
